const bar=document.createElement('section');bar.className='panel project-bar';bar.innerHTML='<button type="button" class="project-title disclosure-button" id="project-toggle" aria-expanded="false" aria-controls="project-content"><strong>'+L('Dự án kỹ thuật','Engineering project')+'</strong><span class="project-title-actions"><span id="project-status"></span><span class="disclosure-state"><span data-disclosure-label>'+L('Hiện','Show')+'</span><span class="disclosure-chevron" aria-hidden="true">⌄</span></span></span></button><div id="project-content" hidden><div class="project-actions"><select id="project-select" aria-label="'+L('Chọn dự án','Select project')+'"></select><button type="button" data-project="new">'+L('+ Dự án mới','+ New project')+'</button><button type="button" data-project="details">'+L('Thông tin','Details')+'</button><button type="button" data-project="export">'+L('Xuất dữ liệu','Export data')+'</button><button type="button" data-project="trash">'+L('Thùng rác','Trash')+'</button><button type="button" data-project="import">'+L('Mở file','Open file')+'</button>'+(key?'<button type="button" data-project="report">'+L('Báo cáo dự án','Project report')+'</button>':'')+'</div><p class="field-help">'+L('Tự lưu trên trình duyệt này. Xuất file JSON để sao lưu hoặc mở trên máy khác. Báo cáo lưu kết quả từng công cụ; khi đổi đầu vào, cần kiểm tra và cập nhật lại các công cụ liên quan.','Autosaved in this browser. Export JSON to back up or open on another device. Reports store each tool result; after changing inputs, review and update dependent tools.')+'</p><input type="file" id="project-file" accept=".json,application/json" hidden></div>';

